(()=>{'use strict';const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>Number(n||0).toLocaleString('fa-IR')+' تومان',admin=location.pathname.startsWith('/admin/');
const errors={domain_already_registered:'این دامنه قبلاً ثبت شده است.',invalid_store_domain:'دامنه را بدون https و مسیر وارد کنید.',reserved_store_domain:'دامنه اصلی فوتوبریج قابل استفاده نیست.',invalid_channel_price:'قیمت معتبر و بیشتر از صفر وارد کنید.',invalid_channel_discount:'تخفیف باید بین صفر و صد درصد باشد.',store_cart_changed:'موجودی کالا برای تأیید این سفارش کافی نیست.',invalid_origin:'نشانی صفحه معتبر نیست.',forbidden:'دسترسی مجاز نیست.'};
async function api(path,options={}){const r=await fetch(path,{...options,headers:{'content-type':'application/json',...options.headers}}),b=await r.json();if(!r.ok)throw Error(errors[b.error]||'عملیات انجام نشد؛ دوباره تلاش کنید.');return b;}function notice(s){$('#notice').textContent=s;}async function run(button,fn){button.disabled=true;notice('');try{await fn();}catch(e){notice(e.message);}finally{button.disabled=false;}}
async function domains(){const [out,network]=await Promise.all([api('/api/admin/storefront/domains'),api('/api/admin/equipment-rental/overview')]);$('#title').textContent='دامنه‌های اختصاصی فروشگاه‌ها';$('#back').href='/admin/equipment-rental';$('#content').innerHTML='<section><h2>ثبت دامنه برای فروشگاه</h2><p>هر دامنه به یک فروشگاه قاب و شاسی یا تجهیزات متصل می‌شود. پس از تأیید اتصال، همان کالاهای فعال در سایت اختصاصی بدون ورود عکاس قابل خرید هستند.</p><form id="domainForm"><label>فروشگاه<select name="shopId" required>'+network.shops.map(s=>'<option value="'+esc(s.id)+'">'+esc(s.name)+'</option>').join('')+'</select></label><label>دامنه<input name="hostname" dir="ltr" placeholder="shop.example.com" required maxlength="253"></label><button class="primary">ثبت دامنه</button></form></section><section><h2>دامنه‌ها و وضعیت اتصال</h2><p>دامنه را در لیارا به همان برنامهٔ فوتوبریج وصل کنید و HTTPS را فعال کنید؛ سپس همین‌جا دامنه را ثبت کنید. اتصال هنگام ثبت خودکار بررسی می‌شود و رکورد TXT جداگانه لازم نیست.</p><p class="muted">دامنه اصلی برنامه: <b dir="ltr">'+esc(out.dnsTarget)+'</b> — مقصد دقیق DNS را از بخش دامنه‌های لیارا بردارید.</p><div id="domains">'+out.domains.map(d=>'<article><div class="row"><b dir="ltr">'+esc(d.hostname)+'</b><span>'+esc(d.shop_name)+'</span><strong>'+(d.active?'فعال':d.verified_at&&d.routed_at?'غیرفعال':'منتظر اتصال در لیارا')+'</strong></div><div class="row"><button data-verify="'+esc(d.hostname)+'">بررسی مجدد اتصال</button><button data-disable="'+esc(d.hostname)+'">غیرفعال کردن</button><a target="_blank" rel="noopener noreferrer" href="https://'+esc(d.hostname)+'">مشاهده سایت</a></div></article>').join('')+'</div></section>';
const selected=new URLSearchParams(location.search).get('shopId');if(selected&&network.shops.some(s=>s.id===selected))$('#domainForm [name=shopId]').value=selected;
$('#domainForm').onsubmit=e=>{e.preventDefault();run(e.submitter,async()=>{const result=await api('/api/admin/storefront/domains',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});await domains();notice(result.status==='active'?'دامنه متصل شد و سایت فروشگاه فعال است.':'دامنه ثبت شد؛ اتصال آن به برنامهٔ فوتوبریج و HTTPS را در لیارا کامل کنید، سپس «بررسی مجدد اتصال» را بزنید.');});};$('#domains').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.disable&&!confirm('فروشگاه روی این دامنه غیرفعال شود؟'))return;run(b,async()=>{const result=await api('/api/admin/storefront/domains/'+encodeURIComponent(b.dataset.verify||b.dataset.disable)+(b.dataset.verify?'/verify':''),{method:b.dataset.verify?'POST':'DELETE',body:b.dataset.verify?'{}':undefined});await domains();notice(result.status==='active'?'دامنه فعال شد.':result.status==='pending_hosting'?'دامنه هنوز به برنامهٔ فوتوبریج وصل نیست یا HTTPS آماده نیست. تنظیمات لیارا را بررسی کنید و دوباره تلاش کنید.':'دامنه غیرفعال شد.');});};}
const states={awaiting_receipt:'در انتظار رسید',pending_review:'بررسی رسید',confirmed:'تأیید شده',in_production:'در حال تولید',ready:'آماده تحویل',delivered:'تحویل شده',cancelled:'لغو شده'},actionTitles={approve:'تأیید رسید و سفارش',reject:'برگرداندن رسید',ready:'آماده تحویل',deliver:'تحویل شد',cancel:'لغو سفارش'};
async function manager(){const [{items},{orders},{bank}]=await Promise.all([api('/api/rental/storefront/items'),api('/api/rental/storefront/orders'),api('/api/rental/storefront/bank')]);$('#content').innerHTML='<section><h2>حساب دریافت وجه فروشگاه</h2><form id="bankForm"><label>صاحب حساب<input name="accountHolder" maxlength="150" value="'+esc(bank.accountHolder)+'"></label><label>شماره کارت<input name="cardNumber" dir="ltr" value="'+esc(bank.cardNumber)+'"></label><label>شبا<input name="iban" dir="ltr" value="'+esc(bank.iban)+'"></label><button class="primary">ذخیره حساب</button></form><small>اطلاعات این حساب پس از ثبت سفارش برای واریز مشتری نمایش داده می‌شود. تغییر حساب روی سفارش‌های قبلی اثر ندارد.</small></section><section><h2>کالاها و قیمت سایت اختصاصی</h2><p>فعال‌بودن، قیمت و تخفیف هر کالا در فوتوبریج و سایت اختصاصی مستقل است. مبلغ‌ها به تومان هستند. برای فعال‌شدن سایت، ادمین فوتوبریج باید دامنه فروشگاه را ثبت و تأیید کند.</p><a class="link" target="_blank" rel="noopener" href="/rental/storefront-preview">پیش‌نمایش سایت عمومی</a> <a class="link" target="_blank" rel="noopener" href="/rental/storefront-preview?sample=1">پیش‌نمایش با محصولات نمونه</a><div id="channels">'+items.map(item=>{const channels=item.variant_specs?.salesChannels||{};return '<article><b>'+esc(item.title)+'</b><small> '+esc([item.variant_specs?.color,item.variant_specs?.widthCm&&item.variant_specs?.heightCm?item.variant_specs.widthCm+'×'+item.variant_specs.heightCm:''].filter(Boolean).join(' · '))+'</small><form data-item="'+esc(item.id)+'"><div class="channels">'+['photobridge','website'].map(key=>{const c=channels[key]||{enabled:key==='photobridge',price:item.sale_price,discountPercent:0};return '<div class="channel"><label><input type="checkbox" name="'+key+'Enabled" '+(c.enabled?'checked':'')+'>'+(key==='website'?'سایت اختصاصی':'فوتوبریج')+'</label><label>قیمت<input class="price" type="number" min="0" max="1000000000000" step="1" name="'+key+'Price" value="'+esc(c.price)+'" required></label><label>تخفیف ٪<input type="number" min="0" max="100" step="0.01" name="'+key+'Discount" value="'+esc(c.discountPercent)+'" required></label></div>';}).join('')+'</div><button class="primary">ذخیره قیمت و انتشار</button></form></article>';}).join('')+'</div></section><section><div class="row"><h2>سفارش‌های سایت اختصاصی</h2><button id="refreshOrders">به‌روزرسانی</button></div><p>این سفارش‌ها متعلق به مشتری عمومی هستند و از سفارش‌های عکاسان جدا نگهداری می‌شوند. واریز مستقیماً به حساب فروشگاه است؛ رسید را پیش از تأیید بررسی کنید.</p><div id="orders">'+(orders.map(o=>{const actions=({awaiting_receipt:['cancel'],pending_review:['approve','reject','cancel'],confirmed:['ready','cancel'],in_production:['ready','cancel'],ready:['deliver','cancel']})[o.status]||[];return '<article><div class="row"><b>'+esc(o.customer_name)+'</b><span dir="ltr">'+esc(o.customer_mobile)+'</span><strong>'+esc(states[o.status])+'</strong><b>'+money(o.total_amount)+'</b></div><small dir="ltr">'+esc(o.hostname)+' · '+esc(o.id)+'</small><div>'+esc(o.delivery_method==='courier'?o.delivery_address:'تحویل حضوری')+'</div><div class="order-items">'+o.items.map(x=>esc(x.title)+' × '+Number(x.quantity)+' — '+money(x.total)).join('<br>')+'</div>'+(o.receipt_submitted_at?'<a target="_blank" rel="noopener" href="/api/rental/storefront/orders/'+esc(o.id)+'/receipt">مشاهده رسید واریز</a>':'')+'<div class="row"><input data-note="'+esc(o.id)+'" maxlength="500" placeholder="توضیح برای مشتری" value="'+esc(o.review_note||'')+'">'+actions.map(a=>'<button data-order="'+esc(o.id)+'" data-action="'+a+'">'+actionTitles[a]+'</button>').join('')+'</div></article>';}).join('')||'<p>هنوز سفارشی ثبت نشده است.</p>')+'</div></section>';
$('#bankForm').onsubmit=e=>{e.preventDefault();run(e.submitter,async()=>{await api('/api/rental/storefront/bank',{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});notice('حساب دریافت وجه ذخیره شد.');});};
$('#channels').onsubmit=e=>{e.preventDefault();const form=e.target;run(e.submitter,async()=>{const salesChannels={};for(const key of ['photobridge','website'])salesChannels[key]={enabled:form.elements[key+'Enabled'].checked,price:Number(form.elements[key+'Price'].value),discountPercent:Number(form.elements[key+'Discount'].value)};await api('/api/rental/storefront/items/'+form.dataset.item,{method:'PUT',body:JSON.stringify({salesChannels})});notice('قیمت و وضعیت انتشار ذخیره شد.');});};$('#refreshOrders').onclick=e=>run(e.target,manager);$('#orders').onclick=e=>{const b=e.target.closest('[data-order]');if(!b)return;if(['cancel','approve'].includes(b.dataset.action)&&!confirm(actionTitles[b.dataset.action]+'؟'))return;run(b,async()=>{await api('/api/rental/storefront/orders/'+b.dataset.order,{method:'PATCH',body:JSON.stringify({action:b.dataset.action,note:document.querySelector('[data-note="'+b.dataset.order+'"]').value})});await manager();notice('وضعیت سفارش ذخیره شد.');});};}
(admin?domains():manager()).catch(e=>{$('#content').textContent=e.message;});})();
